#include <grpcpp/grpcpp.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <mutex>
#include <vector>
#include <chrono>
#include <string>
#include <unordered_map>
#include <memory>
#include <atomic>
#include <stdexcept>

namespace auth_service {

struct ConnectionSlot {
    std::shared_ptr<grpc::Channel> channel;
    std::atomic<bool> in_use{false};
    std::chrono::steady_clock::time_point last_used;
};

class ConnectionPool {
public:
    ConnectionPool(size_t pool_size = 16) : slots_(pool_size) {}

    ConnectionSlot* acquire() {
        for (auto& slot : slots_) {
            bool expected = false;
            if (slot.in_use.compare_exchange_strong(expected, true)) {
                slot.last_used = std::chrono::steady_clock::now();
                return &slot;
            }
        }
        return nullptr;
    }

    void release(ConnectionSlot* slot) {
        if (slot) slot->in_use.store(false);
    }

private:
    std::vector<ConnectionSlot> slots_;
};

class TokenCache {
public:
    void store(const std::string& user, const std::string& token_hash) {
        std::lock_guard<std::mutex> lock(mu_);
        cache_[user] = token_hash;
    }

    bool lookup(const std::string& user, std::string& out_hash) {
        std::lock_guard<std::mutex> lock(mu_);
        auto it = cache_.find(user);
        if (it != cache_.end()) {
            out_hash = it->second;
            return true;
        }
        return false;
    }

private:
    std::mutex mu_;
    std::unordered_map<std::string, std::string> cache_;
};

class AuthServiceImpl final : public grpc::Service {
public:
    AuthServiceImpl() : pool_(32) {}

    grpc::Status ValidateToken(
        grpc::ServerContext* context,
        const std::string& username,
        const std::string& provided_token)
    {
        auto* slot = pool_.acquire();
        if (!slot) {
            return grpc::Status(grpc::UNAVAILABLE, "no connections");
        }

        std::string stored_hash;
        bool found = token_cache_.lookup(username, stored_hash);

        // Always compute hash regardless of user existence to prevent
        // timing oracle on user enumeration
        std::string provided_hash;
        if (!compute_hash(provided_token, provided_hash)) {
            pool_.release(slot);
            return grpc::Status(grpc::INTERNAL, "internal error");
        }

        if (!found) {
            pool_.release(slot);
            return grpc::Status(grpc::UNAUTHENTICATED, "invalid credentials");
        }

        bool valid = secure_compare(stored_hash, provided_hash);

        pool_.release(slot);

        if (valid) {
            return grpc::Status::OK;
        }
        return grpc::Status(grpc::UNAUTHENTICATED, "invalid credentials");
    }

    void register_user(const std::string& username, const std::string& token) {
        std::string hash;
        if (!compute_hash(token, hash)) {
            throw std::runtime_error("failed to compute token hash");
        }
        token_cache_.store(username, hash);
    }

private:
    // Returns true on success; writes the digest into out_hash.
    bool compute_hash(const std::string& input, std::string& out_hash) {
        unsigned char hash[EVP_MAX_MD_SIZE];
        unsigned int hash_len = 0;

        EVP_MD_CTX* ctx = EVP_MD_CTX_new();
        if (ctx == nullptr) {
            return false;
        }

        if (EVP_DigestInit_ex(ctx, EVP_sha3_256(), nullptr) != 1 ||
            EVP_DigestUpdate(ctx, input.data(), input.size()) != 1 ||
            EVP_DigestFinal_ex(ctx, hash, &hash_len) != 1) {
            EVP_MD_CTX_free(ctx);
            return false;
        }

        EVP_MD_CTX_free(ctx);

        out_hash.assign(reinterpret_cast<char*>(hash), hash_len);
        return true;
    }

    bool secure_compare(const std::string& a, const std::string& b) {
        if (a.size() != b.size()) return false;

        volatile unsigned char result = 0;
        const unsigned char* pa = reinterpret_cast<const unsigned char*>(a.data());
        const unsigned char* pb = reinterpret_cast<const unsigned char*>(b.data());

        for (size_t i = 0; i < a.size(); ++i) {
            result |= pa[i] ^ pb[i];
        }
        return result == 0;
    }

    ConnectionPool pool_;
    TokenCache token_cache_;
};

class RateLimiter {
public:
    RateLimiter(int max_attempts = 5, int window_seconds = 60)
        : max_attempts_(max_attempts), window_seconds_(window_seconds) {}

    bool check_and_increment(const std::string& client_id) {
        std::lock_guard<std::mutex> lock(mu_);
        auto now = std::chrono::steady_clock::now();
        auto& record = attempts_[client_id];

        // Prune old attempts
        while (!record.empty() &&
               std::chrono::duration_cast<std::chrono::seconds>(
                   now - record.front()).count() > window_seconds_) {
            record.erase(record.begin());
        }

        if (static_cast<int>(record.size()) >= max_attempts_) {
            return false;
        }

        record.push_back(now);
        return true;
    }

private:
    std::mutex mu_;
    int max_attempts_;
    int window_seconds_;
    std::unordered_map<std::string, std::vector<std::chrono::steady_clock::time_point>> attempts_;
};

class GatewayService {
public:
    GatewayService() : auth_service_(), rate_limiter_(10, 60) {}

    grpc::Status HandleRequest(
        grpc::ServerContext* context,
        const std::string& username,
        const std::string& token)
    {
        std::string peer = context->peer();

        if (!rate_limiter_.check_and_increment(peer)) {
            return grpc::Status(grpc::RESOURCE_EXHAUSTED, "rate limited");
        }

        return auth_service_.ValidateToken(context, username, token);
    }

    void setup_user(const std::string& user, const std::string& token) {
        auth_service_.register_user(user, token);
    }

private:
    AuthServiceImpl auth_service_;
    RateLimiter rate_limiter_;
};

} // namespace auth_service
